/* Build player-facing crop entries from data/crops.json; do not edit outputs. */
const fs = require('node:fs');
const path = require('node:path');
const { renderCropFacts } = require('./render-database-browser.cjs');

const root = path.resolve(__dirname, '..');
const data = JSON.parse(fs.readFileSync(path.join(root, 'data/crops.json'), 'utf8'));
const seedItems = JSON.parse(fs.readFileSync(path.join(root, 'data/build-seeds.json'), 'utf8')).items;
const produceItems = JSON.parse(fs.readFileSync(path.join(root, 'data/build-produce.json'), 'utf8')).items;
const selectedIds = ['red-lettuce', 'garlic', 'strawberry'];
const checkOnly = process.argv.includes('--check');
const escape = value => String(value).replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
const badges = {
  'official': ['Official', '官方'],
  'video-observed': ['Video-observed', '视频观测'],
  video: ['Video-observed', '视频观测'],
  'unverified-lead': ['Single-source', '单一线索'],
  lead: ['Single-source', '单一线索'],
  'shot-pending': ['Image pending', '待补画面'],
  model: ['Theoretical model', '理论模型'],
  unknown: ['Unknown', '未知'],
  historical: ['Historical lead', '历史线索'],
};

function sourceTitle(id, locale) {
  const source = data.sources[id];
  if (!source) throw new Error(`Unknown crop source: ${id}`);
  if (locale === 'zh') {
    if (id === 'games-station-video') return 'Games Station 游戏实录（V0.8.10.455）';
    if (id === 'farmers-land-fandom') return 'Farmer’s Land 玩家资料（历史线索）';
  }
  return source.title;
}

function sources(ids, locale) {
  return [...new Set(ids || [])].map(id => {
    const source = data.sources[id];
    const title = escape(sourceTitle(id, locale));
    return source.url ? `<a href="${escape(source.url)}" rel="noopener noreferrer">${title}</a>` : title;
  }).join(' · ');
}

function cropFacts(entry, locale, keys = null) {
  const zh = locale === 'zh';
  const fields = keys ? entry.fields.filter(field => keys.includes(field.key)) : entry.fields;
  if (zh) {
    const facts = [...new Map(entry.zh.groups.flatMap(group => group.facts).filter(fact => !keys || keys.includes(fact.fieldKey)).map(fact => [fact.text, fact])).values()];
    return facts.map(fact => `<li>${escape(fact.text)} <span class="tag">${badges[fact.badge]?.[1] || '已记录'}</span></li>`).join('');
  }
  const allowedTexts = new Set(fields.flatMap(field => field.facts).map(fact => fact.text));
  const facts = entry.fields.flatMap(field => field.facts).filter(fact => allowedTexts.has(fact.text) && (fact.validity === 'current' || fact.validity === 'unknown'));
  const seen = new Set();
  return facts.filter(fact => !seen.has(fact.text) && seen.add(fact.text)).map(fact => {
    const label = badges[fact.validity === 'unknown' ? 'unknown' : fact.evidenceLevel]?.[0] || 'Recorded';
    const refs = fact.sourceIds?.length ? `<span class="fact-source">${sources(fact.sourceIds, locale)}</span>` : '';
    return `<li>${escape(fact.text)} <span class="tag">${label}</span>${refs}</li>`;
  }).join('');
}

function render(entry, locale) {
  const zh = locale === 'zh';
  const prefix = zh ? '/zh' : '';
  const route = `${prefix}/database/crops/${entry.id}`;
  const counterpart = `${zh ? '' : '/zh'}/database/crops/${entry.id}`;
  const title = zh ? `${entry.zh.name}：种植记录与收益边界 | The Ranchers Guide` : `${entry.name}: Planting Notes & Price Limits | The Ranchers Guide`;
  const summary = zh ? entry.zh.summary : entry.summary;
  const decision = zh ? entry.zh.decision : entry.decision;
  const name = zh ? entry.zh.name : entry.name;
  const itemSources = entry.fields.flatMap(field => field.facts.flatMap(fact => fact.sourceIds || []));
  const sourceNote = [...new Set(itemSources)];
  const config = renderCropFacts(data, entry.id, locale).replace('href="#current-build-crop-roster"', `href="${prefix}/database/crops#current-build-crop-roster"`);
  const links = zh ? [
    ['/zh/database/crops', '返回作物季节对照'],
    ['/zh/guides/farming-fields', '查看种植与浇水步骤'],
    ['/zh/guides/money-making#cashin', '查看 CashIn 出售与到账'],
    ['/zh/map#leafy-market', '定位 Leafy Market'],
  ] : [
    ['/database/crops', 'Compare crops by season'],
    ['/guides/farming-fields', 'Planting and watering steps'],
    ['/guides/money-making#cashin', 'CashIn selling and settlement'],
    ['/map#leafy-market', 'Find Leafy Market'],
  ];
  const seed = seedItems.find(item => item.cropId === entry.id && item.rosterStatus === 'current-roster');
  if (!seed) throw new Error(`Missing current-roster seed for ${entry.id}`);
  const produceAliases = produceItems.filter(item => item.cropId === entry.id).flatMap(item => [item.name, item.zhName, item.id]);
  const pageHtml = `<!doctype html>
<!-- GENERATED by scripts/build-crop-entries.cjs from data/crops.json. -->
<html lang="${zh ? 'zh-CN' : 'en'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escape(title)}</title><meta name="description" content="${escape(summary)}"><link rel="canonical" href="https://theranchersguide.com${route}"><link rel="alternate" hreflang="en" href="https://theranchersguide.com/database/crops/${entry.id}"><link rel="alternate" hreflang="zh-CN" href="https://theranchersguide.com/zh/database/crops/${entry.id}"><link rel="alternate" hreflang="x-default" href="https://theranchersguide.com/database/crops/${entry.id}"><link rel="stylesheet" href="/assets/css/style.css?v=20260902-ui2"><link rel="icon" type="image/png" sizes="32x32" href="/assets/img/favicon-32.png"><script async src="https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=ca-pub-4804883741146501" crossorigin="anonymous"></script></head><body><header class="site-header"><nav class="nav-inner" aria-label="${zh ? '主导航' : 'Main navigation'}"><a class="logo" href="${prefix}/"><span class="logo-mark"><img src="/assets/img/logo.png" alt="" width="34" height="34"></span><span>The Ranchers Guide</span></a><button class="nav-toggle" aria-expanded="false" aria-label="${zh ? '展开导航' : 'Toggle navigation'}">☰</button><ul class="nav-links"><li><a href="${prefix}/guides/beginners-guide">${zh ? '攻略' : 'Guides'}</a></li><li><a class="active" href="${prefix}/database">${zh ? '资料库' : 'Database'}</a></li><li><a href="${prefix}/map">${zh ? '地图' : 'Map'}</a></li><li><a href="${prefix}/problems">${zh ? '问题' : 'Problems'}</a></li><li><a href="${prefix}/search">${zh ? '搜索' : 'Search'}</a></li></ul></nav></header><main><article class="article database-page crop-detail-page" style="max-width:980px"><nav class="breadcrumb" aria-label="${zh ? '面包屑' : 'Breadcrumb'}"><a href="${prefix}/">${zh ? '首页' : 'Home'}</a> / <a href="${prefix}/database">${zh ? '资料库' : 'Database'}</a> / <a href="${prefix}/database/crops">${zh ? '作物' : 'Crops'}</a> / ${escape(name)} / <a class="language-switch" href="${counterpart}">${zh ? 'English' : '中文'}</a></nav><header class="animal-entry-header" id="${entry.id}" data-search-entry data-search-title="${escape(name)}" data-search-aliases="${escape(`${entry.name}|${entry.zh.name}|${entry.id}`)}" data-search-text="${escape(summary)}" data-search-tags="${escape(`${entry.searchTags} ${entry.zh.searchTags}`)}"><p class="kicker">${zh ? '作物词条' : 'Crop profile'}</p><h1>${escape(name)}</h1><p class="lead">${escape(summary)}</p><p class="meta">${zh ? `证据来自 ${data.meta.videoBuild} 公开画面和 ${data.meta.build} 构建配置；没有把配置标成当前实测。` : `Evidence combines public ${data.meta.videoBuild} footage with ${data.meta.build} build settings; configuration is not labeled as current hands-on testing.`}</p></header><section class="crop-snapshot" aria-labelledby="${entry.id}-snapshot"><h2 id="${entry.id}-snapshot">${zh ? '先看种子、季节和收获节奏' : 'Start with seed, season and harvest timing'}</h2>${config}<ul class="evidence-list">${cropFacts(entry, locale, ['seed', 'growth'])}</ul></section><section class="animal-entry-answer"><h2>${zh ? '下一步怎么做' : 'What to do next'}</h2><p>${escape(decision)}</p></section><section class="evidence-ledger" id="price-boundary" data-search-entry data-search-title="${escape(zh ? `${name}价格与收益边界` : `${name} price and income boundary`)}"><h2>${zh ? '价格与收益边界' : 'Price and income boundary'}</h2><ul class="evidence-list">${cropFacts(entry, locale, ['sell'])}</ul></section><section class="evidence-ledger"><h2>${zh ? '来源与完整对照' : 'Sources and full comparison'}</h2><p class="database-browse-note">${zh ? '季节、生长、断水容忍和种子页签来自游戏构建配置；下方链接用于回看完整对照表。' : 'Season, growth, dry tolerance and seed-tab references come from the build configuration; use the link below for the full comparison table.'} <a href="${prefix}/database/crops#current-build-crop-roster">${zh ? '打开完整作物对照表' : 'Open the full crop comparison table'}</a></p><details class="database-reference-notes"><summary>${zh ? '查看来源' : 'Sources'}</summary><p class="fact-source">${sources(sourceNote, locale)}</p></details></section><nav class="animal-next-steps"><h2>${zh ? '继续处理下一步' : 'Next steps'}</h2><ul>${links.map(([href, label]) => `<li><a href="${href}">${label}</a></li>`).join('')}</ul></nav></article></main><footer class="site-footer"><div class="container"><div class="footer-bottom"><span>&copy; <span data-year></span> The Ranchers Guide</span><span>${zh ? '每项内容按来源和证据类型标注' : 'Sources and evidence are labeled for each entry'}</span></div></div></footer><script src="/assets/js/main.js?v=20260927-hash-details1" defer></script></body></html>`;
  const searchAliases = escape([entry.name, entry.zh.name, seed.name, seed.zhName, entry.id, ...produceAliases].join('|'));
  const legacyAliases = escape(`${entry.name}|${entry.zh.name}|${entry.id}`);
  return pageHtml
    .replace(`data-search-aliases="${legacyAliases}"`, `data-search-aliases="${searchAliases}"`)
    .replace(`<li><a href="${prefix}/search">${zh ? '搜索' : 'Search'}</a></li></ul>`, `<li><a href="${prefix}/search">${zh ? '搜索' : 'Search'}</a></li><li><a href="/research">${zh ? '研究' : 'Research'}</a></li><li><a href="/contribute">${zh ? '投稿' : 'Contribute'}</a></li></ul>`);
}

const outputs = selectedIds.flatMap(id => {
  const entry = data.crops.find(crop => crop.id === id);
  if (!entry?.zh) throw new Error(`Missing bilingual crop source: ${id}`);
  return [[`database/crops/${id}.html`, render(entry, 'en')], [`zh/database/crops/${id}.html`, render(entry, 'zh')]];
});
let failed = false;
for (const [relative, expected] of outputs) {
  const target = path.join(root, relative);
  if (checkOnly) {
    if (!fs.existsSync(target) || fs.readFileSync(target, 'utf8') !== expected) {
      console.error(`FAIL: ${relative} is missing or out of sync. Re-run node scripts/build-crop-entries.cjs`);
      failed = true;
    }
  } else {
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.writeFileSync(target, expected);
  }
}
if (failed) process.exitCode = 1;
else if (checkOnly) console.log('PASS: bilingual crop detail routes are in sync with data/crops.json.');
else console.log('Wrote: bilingual Red Lettuce, Garlic and Strawberry detail routes from data/crops.json.');
